ROOT = Path("/Users/billyribeiro/.fanout/wt/verifyE15-BK4-c")
OUT = ROOT / "ledgers/BK4/scripts/BK4-c-r15/out"
CARRY = ("Carried from round 14 (course/modules/BK/BK4/grader/*.py, tests/labs/BK4/*.py, ledgers/BK4/alternatives/*, "
         "course/assets/js/grader.js, rubric.js, labs.js, course/modules/BK/BK4/index.html, L01.html, L03.html: "
         "byte-identical since the round-14 pin 8e5751c9; project.html changed since then only at :466-471):")

mutants = []
for line in (OUT / "mutate_graders_r15.txt").read_text(encoding="utf-8").splitlines():
    m = re.match(r"^KILLED (\S+?): (.*) -> (\S+) \(seed (\d+)\)$", line)
    if m:
        mutants.append({"id": m.group(1), "description": m.group(2), "killed_by": m.group(3)})
assert len(mutants) == 87, len(mutants)

def R(id_, check, location, status, evidence, fix=None):
    row = {"id": id_, "check": check, "location": location, "status": status, "evidence": evidence}
    if status != "PASS":
        row["fix"] = fix
    return row

